// P1 ブランド評判レイヤー: 各ブランドの編集コンテンツ
// 掲載レギュレーション準拠（CLAUDE.md参照: the SILK / 24/7ピラティス / Pilates Mee / zen place）
// 事実ベース原則: 料金・体験・店舗数は data/brands-aggregate.json（掲載実データ）から描画し、
// ここには検証済みの定性情報のみを書く。効果の断定・競合比較での貶め・捏造は禁止。

export type BrandFaq = { q: string; a: string }

// 公式に確認できた全国店舗数（一次情報のみ。確認できないブランドはundefinedのまま＝表示しない）
export type OfficialStores = {
  count: number
  kind: '公式明記' | '一覧実数' // 公式サイトに数字の明記あり／公式店舗一覧を実際に数えた
  approx?: boolean // 「◯店舗以上」等の表現の場合true
  caveat?: string // 数字の但し書き（例: LAVA店内スタジオ含む）。誇張回避のため必ず表示する
  sourceUrl: string
  asOf: string // 取得時点（表示用・例: 2026年7月）
  /** 都道府県別の公式店舗数（公式店舗一覧の住所を数えたもの。合計は count と一致させる）。「{ブランド} 店舗」検索の受け皿（2026-10-11） */
  byPref?: { pref: string; count: number }[]
  /** byPref の合計が count と異なる場合の合計（例: Rintosull＝公式明記の総数270と都道府県別一覧の掲載数299が違う）。2026-10-15 */
  byPrefTotal?: number
  /** 都道府県別の節に出す但し書き（未指定なら caveat を出す）。2026-10-15 */
  byPrefNote?: string
  /** 「全国店舗数」の代わりに出す数の名前（例: LAVA＝マシンピラティス実施店舗数。ブランド全体の店舗数ではない場合に使う）。2026-10-24 */
  countLabel?: string
}

export type BrandInfo = {
  slug: string
  name: string
  tagline: string
  intro: string[]
  features: string[]
  pricingNote: string
  /** 料金プラン欄の先頭に出す一覧（公式の通常料金）。2026-10-09 Pilates Mee（クライアント指示: 一番上に「体験レッスン無料」） */
  priceList?: string[]
  trialNote: string
  goodFor: string[]
  faq: BrandFaq[]
  ctaUrl?: string
  ctaLabel?: string
  officialRef?: { label: string; url: string }
  officialStores?: OfficialStores
  isPartner: boolean
  note?: string
  /** 料金・体験の注記に「キャンペーン」の語を出さない（2026-10-09 Pilates Mee: 消費者庁の指摘を受けクライアントがキャンペーン訴求を全削除） */
  noCampaignWording?: boolean
  /** 別業態の名前。店舗ページ（BrandAreaReceiver）では、店名にこの語を含まない店舗のとき、この語を含む紹介文の文・FAQを出さない（2026-10-09 Pilates Mee大井町店: Mee店舗に5人制コースは無い） */
  subBrandWord?: string
  /** 料金欄の「当サイト掲載店舗の代表的なプラン」表（エリアページ掲載値の頻度集計）を出さない。公式の料金表（priceList）で足り、
      掲載値にキャンペーン表記・店舗ごとの書きぶりの差が混ざるブランド用（2026-10-14 DEP／1to1／Repilates） */
  hideListedPriceTable?: boolean
  /** 公式サイトで料金・店舗数・規約を確認した日（表示用・例: 2026年10月14日）。確認した日だけを書く（ビルド日で自動更新しない） */
  checkedAt?: string
  /** title・h1 の「{ブランド}の◯◯」の◯◯を差し替える（既定は店舗一覧・店舗数・料金…）。「{ブランド} 口コミ」の受け皿で口コミを前に出す用（2026-10-17 Rintosull） */
  titleKw?: string
  nameKana?: string // title・h1 で name の後ろに（）で添える読み（例: the SILK →「ザ シルク」。2026-10-23「シルク ピラティス」13.7位の受け皿）
  /** meta description の差し替え（未指定なら既定文）。2026-10-17 */
  metaDescription?: string
  /** title の「掲載N店舗」だけをこの数に固定する（title を変えてから7日以内に掲載数が変わったとき用。本文・description は実数）。2026-10-30 ルルト */
  titleStoreCount?: number
  /** title 末尾の「｜掲載N店舗を比較」をこの文言に差し替える（公式確認値の答えを出す用）。2026-10-30 pilates K */
  titleSuffix?: string
  /** 料金欄（priceList）の出典リンク（公式ページ）。2026-10-17 */
  priceSources?: { label: string; url: string }[]
  /** 概要ボックスの「代表的なプラン」を掲載値の頻度集計ではなくこの文言にする（公式の料金で書く）。2026-10-24 */
  summaryPlan?: string
  /** 店舗一覧の表の前に出す但し書き（例: LAVA＝掲載店舗のうち公式のマシンピラティス実施店舗一覧に載っている店）。2026-10-24 */
  storeListNote?: string
  /** 特徴の節の後に出す関連ブランドへの導線（役割の違いを1文で添える）。2026-10-24 LAVA⇔Rintosull */
  crossLinks?: { href: string; label: string; text: string }[]
  /** h1 直下の「要点（結論）」＝指名検索（例:「ピラティスk」「ピラティスミー」）への即答。店舗数・料金・体験・場所を公式確認値で1行ずつ。2026-10-26 */
  quickAnswer?: { label: string; text: string; links?: { href: string; label: string }[] }[] // links: 文の後ろに出す内部リンク（2026-10-29 BDC→表参道店ページ）
  /** quickAnswer の出典（公式ページ） */
  quickAnswerSources?: { label: string; url: string }[]
  /** h1 直下（要点の前）に出す公式の料金早見表。「{ブランド} 料金」の答えを最初の画面に置く（2026-11-12 Repilates・La pilates。設定したブランドだけに出る） */
  quickPriceTable?: { rows: { item: string; price: string; note?: string }[]; checkedAt: string; note?: string; sources: { label: string; url: string }[] }
  /** 口コミ節（BrandReviewDigest）の見出しに出す名前（未指定なら name）と、見出し直下の一文。「リピラティス 口コミ」「リ ピラティス 口コミ」の受け皿（2026-11-02 Repilates） */
  reviewName?: string
  reviewLead?: string
  useHyoban: boolean // 掲載評価データが十分（n>=5）な場合のみtitleに「評判」を使う
  reviewThemes?: ReviewThemes // 口コミに多いテーマと注意点（STUDIO_REVIEWS の店舗要約から編集部が整理。stores は STUDIO_REVIEWS のキー）
}

export type ReviewTheme = {
  title: string
  text: string
  stores: string[] // 根拠にした店舗（STUDIO_REVIEWS のキー＝出典リンクに解決される）
}

export type ReviewThemes = {
  basis: string // どのデータから整理したか（表示用）
  good: ReviewTheme[]
  caution: ReviewTheme[]
}

