    pricingNote: '月会費はLAVA（ホットヨガ）の公式料金ページの表記どおりです（2026年10月24日確認）。マシンピラティスは、公式ヘルプセンターではコラボ店でホットヨガと同様に月額内で受講でき、受講回数にカウントされると案内されています（2026年11月24日確認）。例として、マシンピラティス実施店舗の福島黒岩店の店舗ページでは、4・フルタイム 8,800円・ライト・フルタイム 10,800円・プレミアム フリー・フルタイム 16,800円（いずれも税込）が表示されています。11月末までは、当日入会で系列全店の通い放題（16,800円）が3ヶ月間 月1,980円になるキャンペーンが案内されています（3ヶ月目に5,940円をまとめて請求）。公式料金ページでは、特典の適用には特別価格の終了後12ヶ月間の継続が必要で、過去5ヶ月以内に体験・見学をした人などは対象外とされています（2026年11月24日確認）。',
    trialNote: '公式サイトでは体験レッスンは0円（税込）で、ウェアやタオルを借りられます。マシンピラティスで体験できるのは、公式ページで「体験レッスン可能」と表示されたプログラム（Basic+・Upper Body Make-up+・Lower Body Make-up＋・Hip&Legs+・Waist Shape+、ホットマシピラの Upper Body・Lower Body・Hot Stretch Release）です。福島黒岩店の店舗ページでは「選べる体験レッスン」としてヨガかマシンピラティスを選べます（2026年10月24日確認）。',
